import sys
def solve(n, dims):
    # n is number of matrices, dims is n+1
    # dp[i][j] is min cost for matrices i..j (1-indexed)
    m = [[0] * (n + 1) for _ in range(n + 1)]
    for length in range(2, n + 1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k+1][j] + dims[i-1]*dims[k]*dims[j]
                if q < m[i][j]: m[i][j] = q
    return str(m[1][n])

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data: sys.exit(0)
    n = int(data[0])
    dims = list(map(int, data[1:2+n]))
    print(solve(n, dims))

